6|# Three.js Lighting
7|
8|## Quick Start
9|
10|```javascript
11|import * as THREE from "three";
12|
13|// Basic lighting setup
14|const ambientLight = new THREE.AmbientLight(0xffffff, 0.5);
15|scene.add(ambientLight);
16|
17|const directionalLight = new THREE.DirectionalLight(0xffffff, 1);
18|directionalLight.position.set(5, 5, 5);
19|scene.add(directionalLight);
20|```
21|
22|## Light Types Overview
23|
24|| Light            | Description            | Shadow Support | Cost     |
25|| ---------------- | ---------------------- | -------------- | -------- |
26|| AmbientLight     | Uniform everywhere     | No             | Very Low |
27|| HemisphereLight  | Sky/ground gradient    | No             | Very Low |
28|| DirectionalLight | Parallel rays (sun)    | Yes            | Low      |
29|| PointLight       | Omnidirectional (bulb) | Yes            | Medium   |
30|| SpotLight        | Cone-shaped            | Yes            | Medium   |
31|| RectAreaLight    | Area light (window)    | No\*           | High     |
32|
33|\*RectAreaLight shadows require custom solutions
34|
35|## AmbientLight
36|
37|Illuminates all objects equally. No direction, no shadows.
38|
39|```javascript
40|// AmbientLight(color, intensity)
41|const ambient = new THREE.AmbientLight(0xffffff, 0.5);
42|scene.add(ambient);
43|
44|// Modify at runtime
45|ambient.color.set(0xffffcc);
46|ambient.intensity = 0.3;
47|```
48|
49|## HemisphereLight
50|
51|Gradient from sky to ground color. Good for outdoor scenes.
52|
53|```javascript
54|// HemisphereLight(skyColor, groundColor, intensity)
55|const hemi = new THREE.HemisphereLight(0x87ceeb, 0x8b4513, 0.6);
56|hemi.position.set(0, 50, 0);
57|scene.add(hemi);
58|
59|// Properties
60|hemi.color; // Sky color
61|hemi.groundColor; // Ground color
62|hemi.intensity;
63|```
64|
65|## DirectionalLight
66|
67|Parallel light rays. Simulates distant light source (sun).
68|
69|```javascript
70|// DirectionalLight(color, intensity)
71|const dirLight = new THREE.DirectionalLight(0xffffff, 1);
72|dirLight.position.set(5, 10, 5);
73|
74|// Light points at target (default: 0, 0, 0)
75|dirLight.target.position.set(0, 0, 0);
76|scene.add(dirLight.target);
77|
78|scene.add(dirLight);
79|```
80|
81|### DirectionalLight Shadows
82|
83|```javascript
84|dirLight.castShadow = true;
85|
86|// Shadow map size (higher = sharper, more expensive)
87|dirLight.shadow.mapSize.width = 2048;
88|dirLight.shadow.mapSize.height = 2048;
89|
90|// Shadow camera (orthographic)
91|dirLight.shadow.camera.near = 0.5;
92|dirLight.shadow.camera.far = 50;
93|dirLight.shadow.camera.left = -10;
94|dirLight.shadow.camera.right = 10;
95|dirLight.shadow.camera.top = 10;
96|dirLight.shadow.camera.bottom = -10;
97|
98|// Shadow softness
99|dirLight.shadow.radius = 4; // Blur radius (PCFSoftShadowMap only)
100|
101|// Shadow bias (fixes shadow acne)
102|dirLight.shadow.bias = -0.0001;
103|dirLight.shadow.normalBias = 0.02;
104|
105|// Helper to visualize shadow camera
106|const helper = new THREE.CameraHelper(dirLight.shadow.camera);
107|scene.add(helper);
108|```
109|
110|## PointLight
111|
112|Emits light in all directions from a point. Like a light bulb.
113|
114|```javascript
115|// PointLight(color, intensity, distance, decay)
116|const pointLight = new THREE.PointLight(0xffffff, 1, 100, 2);
117|pointLight.position.set(0, 5, 0);
118|scene.add(pointLight);
119|
120|// Properties
121|pointLight.distance; // Maximum range (0 = infinite)
122|pointLight.decay; // Light falloff (physically correct = 2)
123|```
124|
125|### PointLight Shadows
126|
127|```javascript
128|pointLight.castShadow = true;
129|pointLight.shadow.mapSize.width = 1024;
130|pointLight.shadow.mapSize.height = 1024;
131|
132|// Shadow camera (perspective - 6 directions for cube map)
133|pointLight.shadow.camera.near = 0.5;
134|pointLight.shadow.camera.far = 50;
135|
136|pointLight.shadow.bias = -0.005;
137|```
138|
139|## SpotLight
140|
141|Cone-shaped light. Like a flashlight or stage light.
142|
143|```javascript
144|// SpotLight(color, intensity, distance, angle, penumbra, decay)
145|const spotLight = new THREE.SpotLight(0xffffff, 1, 100, Math.PI / 6, 0.5, 2);
146|spotLight.position.set(0, 10, 0);
147|
148|// Target (light points at this)
149|spotLight.target.position.set(0, 0, 0);
150|scene.add(spotLight.target);
151|
152|scene.add(spotLight);
153|
154|// Properties
155|spotLight.angle; // Cone angle (radians, max Math.PI/2)
156|spotLight.penumbra; // Soft edge (0-1)
157|spotLight.distance; // Range
158|spotLight.decay; // Falloff
159|```
