179|## RectAreaLight
180|
181|Rectangular area light. Great for soft, realistic lighting.
182|
183|```javascript
184|import { RectAreaLightHelper } from "three/examples/jsm/helpers/RectAreaLightHelper.js";
185|import { RectAreaLightUniformsLib } from "three/examples/jsm/lights/RectAreaLightUniformsLib.js";
186|
187|// Must initialize uniforms first
188|RectAreaLightUniformsLib.init();
189|
190|// RectAreaLight(color, intensity, width, height)
191|const rectLight = new THREE.RectAreaLight(0xffffff, 5, 4, 2);
192|rectLight.position.set(0, 5, 0);
193|rectLight.lookAt(0, 0, 0);
194|scene.add(rectLight);
195|
196|// Helper
197|const helper = new RectAreaLightHelper(rectLight);
198|rectLight.add(helper);
199|
200|// Note: Only works with MeshStandardMaterial and MeshPhysicalMaterial
201|// Does not cast shadows natively
202|```
203|
204|## Shadow Setup
205|
206|### Enable Shadows
207|
208|```javascript
209|// 1. Enable on renderer
210|renderer.shadowMap.enabled = true;
211|renderer.shadowMap.type = THREE.PCFSoftShadowMap;
212|
213|// Shadow map types:
214|// THREE.BasicShadowMap - fastest, low quality
215|// THREE.PCFShadowMap - default, filtered
216|// THREE.PCFSoftShadowMap - softer edges
217|// THREE.VSMShadowMap - variance shadow map
218|
219|// 2. Enable on light
220|light.castShadow = true;
221|
222|// 3. Enable on objects
223|mesh.castShadow = true;
224|mesh.receiveShadow = true;
225|
226|// Ground plane
227|floor.receiveShadow = true;
228|floor.castShadow = false; // Usually false for floors
229|```
230|
231|### Optimizing Shadows
232|
233|```javascript
234|// Tight shadow camera frustum
235|const d = 10;
236|dirLight.shadow.camera.left = -d;
237|dirLight.shadow.camera.right = d;
238|dirLight.shadow.camera.top = d;
239|dirLight.shadow.camera.bottom = -d;
240|dirLight.shadow.camera.near = 0.5;
241|dirLight.shadow.camera.far = 30;
242|
243|// Fix shadow acne
244|dirLight.shadow.bias = -0.0001; // Depth bias
245|dirLight.shadow.normalBias = 0.02; // Bias along normal
246|
247|// Shadow map size (balance quality vs performance)
248|// 512 - low quality
249|// 1024 - medium quality
250|// 2048 - high quality
251|// 4096 - very high quality (expensive)
252|```
253|
254|### Contact Shadows (Fake, Fast)
255|
256|```javascript
257|import { ContactShadows } from "three/examples/jsm/objects/ContactShadows.js";
258|
259|const contactShadows = new ContactShadows({
260|  resolution: 512,
261|  blur: 2,
262|  opacity: 0.5,
263|  scale: 10,
264|  position: [0, 0, 0],
265|});
266|scene.add(contactShadows);
267|```
