269|## Light Helpers
270|
271|```javascript
272|import { RectAreaLightHelper } from "three/examples/jsm/helpers/RectAreaLightHelper.js";
273|
274|// DirectionalLight helper
275|const dirHelper = new THREE.DirectionalLightHelper(dirLight, 5);
276|scene.add(dirHelper);
277|
278|// PointLight helper
279|const pointHelper = new THREE.PointLightHelper(pointLight, 1);
280|scene.add(pointHelper);
281|
282|// SpotLight helper
283|const spotHelper = new THREE.SpotLightHelper(spotLight);
284|scene.add(spotHelper);
285|
286|// Hemisphere helper
287|const hemiHelper = new THREE.HemisphereLightHelper(hemiLight, 5);
288|scene.add(hemiHelper);
289|
290|// RectAreaLight helper
291|const rectHelper = new RectAreaLightHelper(rectLight);
292|rectLight.add(rectHelper);
293|
294|// Update helpers when light changes
295|dirHelper.update();
296|spotHelper.update();
297|```
