299|## Environment Lighting (IBL)
300|
301|Image-Based Lighting using HDR environment maps.
302|
303|```javascript
304|import { RGBELoader } from "three/examples/jsm/loaders/RGBELoader.js";
305|
306|const rgbeLoader = new RGBELoader();
307|rgbeLoader.load("environment.hdr", (texture) => {
308|  texture.mapping = THREE.EquirectangularReflectionMapping;
309|
310|  // Set as scene environment (affects all PBR materials)
311|  scene.environment = texture;
312|
313|  // Optional: also use as background
314|  scene.background = texture;
315|  scene.backgroundBlurriness = 0; // 0-1, blur the background
316|  scene.backgroundIntensity = 1;
317|});
318|
319|// PMREMGenerator for better reflections
320|const pmremGenerator = new THREE.PMREMGenerator(renderer);
321|pmremGenerator.compileEquirectangularShader();
322|
323|rgbeLoader.load("environment.hdr", (texture) => {
324|  const envMap = pmremGenerator.fromEquirectangular(texture).texture;
325|  scene.environment = envMap;
326|  texture.dispose();
327|  pmremGenerator.dispose();
328|});
329|```
330|
331|### Cube Texture Environment
332|
333|```javascript
334|const cubeLoader = new THREE.CubeTextureLoader();
335|const envMap = cubeLoader.load([
336|  "px.jpg",
337|  "nx.jpg",
338|  "py.jpg",
339|  "ny.jpg",
340|  "pz.jpg",
341|  "nz.jpg",
342|]);
343|
344|scene.environment = envMap;
345|scene.background = envMap;
346|```
