251|// 4096 - very high quality (expensive)
252|```
253|
254|### Contact Shadows (Fake, Fast)
255|
256|```javascript
257|import { ContactShadows } from "three/examples/jsm/objects/ContactShadows.js";
258|
259|const contactShadows = new ContactShadows({
260|  resolution: 512,
261|  blur: 2,
262|  opacity: 0.5,
263|  scale: 10,
264|  position: [0, 0, 0],
265|});
266|scene.add(contactShadows);
267|```
268|
269|## Light Helpers
270|
271|```javascript
272|import { RectAreaLightHelper } from "three/examples/jsm/helpers/RectAreaLightHelper.js";
273|
274|// DirectionalLight helper
275|const dirHelper = new THREE.DirectionalLightHelper(dirLight, 5);
276|scene.add(dirHelper);
277|
278|// PointLight helper
279|const pointHelper = new THREE.PointLightHelper(pointLight, 1);
280|scene.add(pointHelper);
281|
282|// SpotLight helper
283|const spotHelper = new THREE.SpotLightHelper(spotLight);
284|scene.add(spotHelper);
285|
286|// Hemisphere helper
287|const hemiHelper = new THREE.HemisphereLightHelper(hemiLight, 5);
288|scene.add(hemiHelper);
289|
290|// RectAreaLight helper
291|const rectHelper = new RectAreaLightHelper(rectLight);
292|rectLight.add(rectHelper);
293|
294|// Update helpers when light changes
295|dirHelper.update();
296|spotHelper.update();
297|```
298|
299|## Environment Lighting (IBL)
300|
301|Image-Based Lighting using HDR environment maps.
302|
303|```javascript
304|import { RGBELoader } from "three/examples/jsm/loaders/RGBELoader.js";
305|
306|const rgbeLoader = new RGBELoader();
307|rgbeLoader.load("environment.hdr", (texture) => {
308|  texture.mapping = THREE.EquirectangularReflectionMapping;
309|
310|  // Set as scene environment (affects all PBR materials)
311|  scene.environment = texture;
312|
313|  // Optional: also use as background
314|  scene.background = texture;
315|  scene.backgroundBlurriness = 0; // 0-1, blur the background
316|  scene.backgroundIntensity = 1;
317|});
318|
319|// PMREMGenerator for better reflections
320|const pmremGenerator = new THREE.PMREMGenerator(renderer);
321|pmremGenerator.compileEquirectangularShader();
322|
323|rgbeLoader.load("environment.hdr", (texture) => {
324|  const envMap = pmremGenerator.fromEquirectangular(texture).texture;
325|  scene.environment = envMap;
326|  texture.dispose();
327|  pmremGenerator.dispose();
328|});
329|```
330|
331|### Cube Texture Environment
332|
333|```javascript
334|const cubeLoader = new THREE.CubeTextureLoader();
335|const envMap = cubeLoader.load([
336|  "px.jpg",
337|  "nx.jpg",
338|  "py.jpg",
339|  "ny.jpg",
340|  "pz.jpg",
341|  "nz.jpg",
342|]);
343|
344|scene.environment = envMap;
345|scene.background = envMap;
346|```
347|
348|## Light Probes (Advanced)
349|
350|Capture lighting from a point in space for ambient lighting.
351|
352|```javascript
353|import { LightProbeGenerator } from "three/examples/jsm/lights/LightProbeGenerator.js";
354|
355|// Generate from cube texture
356|const lightProbe = new THREE.LightProbe();
357|scene.add(lightProbe);
358|
359|lightProbe.copy(LightProbeGenerator.fromCubeTexture(cubeTexture));
360|
361|// Or from render target
362|const cubeCamera = new THREE.CubeCamera(
363|  0.1,
364|  100,
365|  new THREE.WebGLCubeRenderTarget(256),
366|);
367|cubeCamera.update(renderer, scene);
368|lightProbe.copy(
369|  LightProbeGenerator.fromCubeRenderTarget(renderer, cubeCamera.renderTarget),
370|);
371|```
372|
373|## Common Lighting Setups
374|
375|### Three-Point Lighting
376|
377|```javascript
378|// Key light (main light)
379|const keyLight = new THREE.DirectionalLight(0xffffff, 1);
380|keyLight.position.set(5, 5, 5);
381|scene.add(keyLight);
382|
383|// Fill light (softer, opposite side)
384|const fillLight = new THREE.DirectionalLight(0xffffff, 0.5);
385|fillLight.position.set(-5, 3, 5);
386|scene.add(fillLight);
387|
388|// Back light (rim lighting)
389|const backLight = new THREE.DirectionalLight(0xffffff, 0.3);
390|backLight.position.set(0, 5, -5);
391|scene.add(backLight);
392|
393|// Ambient fill
394|const ambient = new THREE.AmbientLight(0x404040, 0.3);
395|scene.add(ambient);
396|```
397|
398|### Outdoor Daylight
399|
400|```javascript
401|// Sun
402|const sun = new THREE.DirectionalLight(0xffffcc, 1.5);
403|sun.position.set(50, 100, 50);
404|sun.castShadow = true;
405|scene.add(sun);
406|
407|// Sky ambient
408|const hemi = new THREE.HemisphereLight(0x87ceeb, 0x8b4513, 0.6);
409|scene.add(hemi);
410|```
411|
412|### Indoor Studio
413|
414|```javascript
415|// Multiple area lights
416|RectAreaLightUniformsLib.init();
417|
418|const light1 = new THREE.RectAreaLight(0xffffff, 5, 2, 2);
419|light1.position.set(3, 3, 3);
420|light1.lookAt(0, 0, 0);
421|scene.add(light1);
422|
423|const light2 = new THREE.RectAreaLight(0xffffff, 3, 2, 2);
424|light2.position.set(-3, 3, 3);
425|light2.lookAt(0, 0, 0);
426|scene.add(light2);
427|
428|// Ambient fill
429|const ambient = new THREE.AmbientLight(0x404040, 0.2);
430|scene.add(ambient);
431|```
432|
433|## Light Animation
434|
435|```javascript
436|const clock = new THREE.Clock();
437|
438|function animate() {
439|  const time = clock.getElapsedTime();
440|
441|  // Orbit light around scene
442|  light.position.x = Math.cos(time) * 5;
443|  light.position.z = Math.sin(time) * 5;
444|
445|  // Pulsing intensity
446|  light.intensity = 1 + Math.sin(time * 2) * 0.5;
447|
448|  // Color cycling
449|  light.color.setHSL((time * 0.1) % 1, 1, 0.5);
450|
451|  // Update helpers if using
452|  lightHelper.update();
453|}
454|```
455|
456|## Performance Tips
457|
458|1. **Limit light count**: Each light adds shader complexity
459|2. **Use baked lighting**: For static scenes, bake to textures
460|3. **Smaller shadow maps**: 512-1024 often sufficient
461|4. **Tight shadow frustums**: Only cover needed area
462|5. **Disable unused shadows**: Not all lights need shadows
463|6. **Use light layers**: Exclude objects from certain lights
464|
465|```javascript
466|// Light layers
467|light.layers.set(1); // Light only affects layer 1
468|mesh.layers.enable(1); // Mesh is on layer 1
469|otherMesh.layers.disable(1); // Other mesh not affected
470|
471|// Selective shadows
472|mesh.castShadow = true;
473|mesh.receiveShadow = true;
474|decorMesh.castShadow = false; // Small objects often don't need to cast
475|```
476|
